    width: u32,
    height: u32,
    limit: u32,
    pad: u32,
    x0: f32,
    y0: f32,
    dx: f32,
    dy: f32,
}

@group(0) @binding(0) var<uniform> p: Params;
@group(0) @binding(1) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= p.width || id.y >= p.height) {
        return;
    }
    let cx = p.x0 + (f32(id.x) + 0.5) * p.dx;
    let cy = p.y0 + (f32(id.y) + 0.5) * p.dy;
    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    while (n < p.limit && zx * zx + zy * zy <= 4.0) {
        let t = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = t;
        n = n + 1u;
    }
    out[id.y * p.width + id.x] = n;
}
"#;

struct Job {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse(path: &str) -> Result<Job, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
    let mut tok = text.split_whitespace();
    let mut next = || tok.next().ok_or_else(|| "missing value".to_string());
    let int = |s: &str| s.parse::<u32>().map_err(|e| format!("{s}: {e}"));
    let num = |s: &str| s.parse::<f64>().map_err(|e| format!("{s}: {e}"));
    Ok(Job {
        width: int(next()?)?,
        height: int(next()?)?,
        limit: int(next()?)?,
        x_min: num(next()?)?,
        x_max: num(next()?)?,
        y_min: num(next()?)?,
        y_max: num(next()?)?,
    })
}

fn compute(job: &Job) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let count = job.width as u64 * job.height as u64;
    let size = count * 4;

    let dx = (job.x_max - job.x_min) / job.width as f64;
    let dy = (job.y_max - job.y_min) / job.height as f64;
    let mut raw = Vec::new();
    for v in [job.width, job.height, job.limit, 0] {
        raw.extend_from_slice(&v.to_le_bytes());
    }
    for v in [job.x_min as f32, job.y_min as f32, dx as f32, dy as f32] {
        raw.extend_from_slice(&v.to_le_bytes());
    }

    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: &raw,
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let out = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let staging = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let bind = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: params.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: out.as_entire_binding() },
        ],
    });

    let mut enc = device.create_command_encoder(&Default::default());
    {
        let mut pass = enc.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind, &[]);
        pass.dispatch_workgroups(job.width.div_ceil(8), job.height.div_ceil(8), 1);
    }
    enc.copy_buffer_to_buffer(&out, 0, &staging, 0, size);
    queue.submit([enc.finish()]);

    let slice = staging.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll: {e}"))?;
    rx.recv().map_err(|e| e.to_string())?.map_err(|e| e.to_string())?;
    let data = slice.get_mapped_range();
    Ok(data.chunks_exact(4).map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect())
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: escape <input-file>");
        return ExitCode::FAILURE;
    };
    let result = parse(&path).and_then(|job| compute(&job).map(|t| (job, t)));
    let (job, times) = match result {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };

    let mut inside = 0u64;
    let mut bins = [0u64; 8];
    let mut sum = 0u64;
    let mut escaped = 0u64;
    for &n in &times {
        if n >= job.limit {
            inside += 1;
        } else {
            bins[(8 * n as u64 / job.limit as u64) as usize] += 1;
            sum += n as u64;
            escaped += 1;
        }
    }
    let mean = if escaped == 0 { 0.0 } else { sum as f64 / escaped as f64 };
    println!("INSIDE {inside}");
    for (i, b) in bins.iter().enumerate() {
        println!("BIN {i} {b}");
    }
    println!("MEAN {mean:.3}");
    ExitCode::SUCCESS
}
